-- 2026-10-31d: MP Background timelines for 20 Cabinet MPs, batch 4 (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (264 entries, copied exactly from the batch 4 data file, which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 1446, 1510, 3914, 4038, 4046, 4077, 4082, 4119, 4263, 4359, 4473, 4504, 4620, 4641, 491, 5038, 5039, 5148, 529, 632,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate() and every source
-- link was checked. Nothing else changes. No code change. Backup of the 20 rows, off the repo:
-- "Claude outputs/backups/2026-10-31d-mp-biography-before.csv".
-- Guards (RAISE): exactly 20 rows change, all of them these 20; the 29 existing timelines are unchanged (md5);
-- MPs with a timeline go from 29 to 49; each array equals the file exactly; 639 entries in all afterwards.
-- Undo: 2026-10-31d-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (1446, 1510, 3914, 4038, 4046, 4077, 4082, 4119, 4263, 4359, 4473, 4504, 4620, 4641, 491, 5038, 5039, 5148, 529, 632)) <> 20 THEN RAISE EXCEPTION 'expected 20 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (1446, 1510, 3914, 4038, 4046, 4077, 4082, 4119, 4263, 4359, 4473, 4504, 4620, 4641, 491, 5038, 5039, 5148, 529, 632) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a batch 4 MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 29 THEN RAISE EXCEPTION 'expected 29 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO bt_new (member_id, n, tl) VALUES
