  (4082, 12, $bt$[{"phase":"education","start":null,"end":null,"title":"Parrs Wood High School","organisation":"Parrs Wood High School, Manchester","detail":"Attended Parrs Wood High School.","source":{"title":"politics.co.uk: Lisa Nandy","url":"https://www.politics.co.uk/people/lisa-nandy/"}},{"phase":"education","start":null,"end":null,"title":"Holy Cross College","organisation":"Holy Cross College, Bury","detail":"Attended Holy Cross College in Bury.","source":{"title":"politics.co.uk: Lisa Nandy","url":"https://www.politics.co.uk/people/lisa-nandy/"}},{"phase":"education","start":null,"end":"2001","title":"Degree in politics","organisation":"Newcastle University","detail":"Studied politics, graduating in 2001.","source":{"title":"GOV.UK: The Rt Hon Lisa Nandy MP","url":"https://www.gov.uk/government/people/lisa-nandy"}},{"phase":"education","start":null,"end":null,"title":"Master's degree in public policy","organisation":"Birkbeck, University of London","detail":"Obtained a master's degree in public policy.","source":{"title":"GOV.UK: The Rt Hon Lisa Nandy MP","url":"https://www.gov.uk/government/people/lisa-nandy"}},{"phase":"career","start":null,"end":null,"title":"Researcher and caseworker","organisation":"Office of Neil Gerrard MP","detail":"Worked as a researcher and caseworker for the Labour MP for Walthamstow, Neil Gerrard.","source":{"title":"politics.co.uk: Lisa Nandy","url":"https://www.politics.co.uk/people/lisa-nandy/"}},{"phase":"career","start":"2003","end":"2005","title":"Researcher","organisation":"Centrepoint","detail":"Worked as a researcher at the homelessness charity Centrepoint.","source":{"title":"GOV.UK: The Rt Hon Lisa Nandy MP","url":"https://www.gov.uk/government/people/lisa-nandy"}},{"phase":"career","start":"2005","end":"2010","title":"Senior policy adviser","organisation":"The Children's Society","detail":"Worked as senior policy adviser at The Children's Society.","source":{"title":"GOV.UK: The Rt Hon Lisa Nandy MP","url":"https://w