  (4119, 16, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Houghton Kepier Comprehensive School","detail":"He attended Houghton Kepier Comprehensive School.","source":{"title":"politics.co.uk: Jonathan Reynolds","url":"https://www.politics.co.uk/people/jonathan-reynolds/"}},{"phase":"education","start":null,"end":null,"title":"Further education","organisation":"Sunderland City College","detail":"He attended Sunderland City College.","source":{"title":"politics.co.uk: Jonathan Reynolds","url":"https://www.politics.co.uk/people/jonathan-reynolds/"}},{"phase":"education","start":"1998","end":"1998","title":"Moved to Manchester for university","organisation":"University of Manchester","detail":"He moved to the North West in 1998 to attend Manchester University.","source":{"title":"PPC Profile: Jonathan Reynolds (LabourList)","url":"https://labourlist.org/2010/04/ppc-profile-jonathan-reynolds/"}},{"phase":"education","start":null,"end":null,"title":"Politics and modern history","organisation":"University of Manchester","detail":"He studied politics and modern history at the University of Manchester.","source":{"title":"politics.co.uk: Jonathan Reynolds","url":"https://www.politics.co.uk/people/jonathan-reynolds/"}},{"phase":"education","start":null,"end":null,"title":"Law","organisation":"BPP Law School, Manchester","detail":"He later studied law at BPP Law School in Manchester.","source":{"title":"politics.co.uk: Jonathan Reynolds","url":"https://www.politics.co.uk/people/jonathan-reynolds/"}},{"phase":"career","start":null,"end":null,"title":"Council employee","organisation":null,"detail":"After university he worked for a council.","source":{"title":"PPC Profile: Jonathan Reynolds (LabourList)","url":"https://labourlist.org/2010/04/ppc-profile-jonathan-reynolds/"}},{"phase":"career","start":null,"end":null,"title":"Political assistant to James Purnell MP","organisation":"House of Commons","detail":"He worked as a politi