  (4263, 18, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Parrs Wood High School, Didsbury","detail":"She attended Parrs Wood High School in Didsbury.","source":{"title":"politics.co.uk: Lucy Powell","url":"https://www.politics.co.uk/people/lucy-powell/"}},{"phase":"education","start":null,"end":null,"title":"Sixth form","organisation":"Xaverian College","detail":"She attended Xaverian College after Parrs Wood High School.","source":{"title":"politics.co.uk: Lucy Powell","url":"https://www.politics.co.uk/people/lucy-powell/"}},{"phase":"education","start":"1993","end":null,"title":"Chemistry","organisation":"Somerville College, University of Oxford","detail":"She went to Oxford in 1993 to study chemistry and stayed one year before moving to King's College London.","source":{"title":"Who is new deputy Labour leader Lucy Powell? (BBC News)","url":"https://www.bbc.co.uk/news/articles/cev1d30kjdlo"}},{"phase":"education","start":null,"end":null,"title":"Chemistry degree","organisation":"King's College London","detail":"She transferred to King's College London in her second year and completed her degree there.","source":{"title":"'I quit Oxford, it was like Hogwarts': Labour's Lucy Powell on clubbing and class (The i Paper)","url":"https://inews.co.uk/news/politics/i-quit-oxford-it-was-like-hogwarts-labours-lucy-powell-on-clubbing-and-class-3053305"}},{"phase":"career","start":null,"end":null,"title":"Part time job","organisation":"Inman's newsagent, Didsbury","detail":"She had a part time job at Inman's, a newsagent near her Didsbury home, while studying for her A levels.","source":{"title":"'I quit Oxford, it was like Hogwarts': Labour's Lucy Powell on clubbing and class (The i Paper)","url":"https://inews.co.uk/news/politics/i-quit-oxford-it-was-like-hogwarts-labours-lucy-powell-on-clubbing-and-class-3053305"}},{"phase":"career","start":null,"end":null,"title":"Saturday job","organisation":"Topshop","detail":"She had 