  (4359, 13, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Drayton Manor High School","detail":"Attended Drayton Manor High School in London.","source":{"title":"politics.co.uk: Stephen Kinnock","url":"https://www.politics.co.uk/people/stephen-kinnock/"}},{"phase":"education","start":null,"end":null,"title":"Modern Languages","organisation":"Queens' College, University of Cambridge","detail":"Studied modern languages at Queens' College, Cambridge.","source":{"title":"politics.co.uk: Stephen Kinnock","url":"https://www.politics.co.uk/people/stephen-kinnock/"}},{"phase":"education","start":"1992","end":"1993","title":"Master's degree","organisation":"College of Europe, Bruges","detail":"Took a master's degree at the College of Europe in Bruges after winning a scholarship.","source":{"title":"politics.co.uk: Stephen Kinnock","url":"https://www.politics.co.uk/people/stephen-kinnock/"}},{"phase":"career","start":null,"end":null,"title":"Research assistant","organisation":"European Parliament","detail":"Worked as a research assistant at the European Parliament before joining the British Council.","source":{"title":"Wikipedia: Stephen Kinnock","url":"https://en.wikipedia.org/wiki/Stephen_Kinnock"}},{"phase":"career","start":"1997","end":null,"title":"Development and Training Services executive","organisation":"British Council","detail":"Joined the British Council in Brussels as a Development and Training Services executive.","source":{"title":"Wikipedia: Stephen Kinnock","url":"https://en.wikipedia.org/wiki/Stephen_Kinnock"}},{"phase":"career","start":null,"end":null,"title":"Programme Leader, Inter-Cultural Dialogue","organisation":"British Council","detail":"Led the design and development of the Sharing Futures programme.","source":{"title":"European Leadership Network: Stephen Kinnock","url":"https://europeanleadershipnetwork.org/person/stephen-kinnock/"}},{"phase":"career","start":null,"end":null,"title":"Director, Brus