  (4473, 14, $bt$[{"phase":"education","start":null,"end":"2005","title":"Sheffield High School","organisation":"Sheffield High School","detail":"Attended Sheffield High School, an independent school, finishing in 2005.","source":{"title":"Schools Week: Louise Haigh, shadow digital minister","url":"https://schoolsweek.co.uk/20899/"}},{"phase":"education","start":null,"end":null,"title":"Undergraduate study at the London School of Economics (not completed)","organisation":"London School of Economics","detail":"Began studying at the London School of Economics and moved to the University of Nottingham after disliking student life there.","source":{"title":"Schools Week: Louise Haigh, shadow digital minister","url":"https://schoolsweek.co.uk/20899/"}},{"phase":"education","start":"2008","end":"2008","title":"BA Politics and Economics","organisation":"University of Nottingham","detail":"Graduated from the University of Nottingham with a BA in politics and economics in 2008.","source":{"title":"Schools Week: Louise Haigh, shadow digital minister","url":"https://schoolsweek.co.uk/20899/"}},{"phase":"education","start":"2010","end":"2010","title":"LLM International Law","organisation":"Birkbeck, University of London","detail":"Completed an LLM in international law at Birkbeck in 2010.","source":{"title":"Schools Week: Louise Haigh, shadow digital minister","url":"https://schoolsweek.co.uk/20899/"}},{"phase":"career","start":"2006","end":"2008","title":"Training administrator, Youth Service","organisation":"Nottingham City Council","detail":"Worked as a training administrator in the Nottingham City Council Youth Service.","source":{"title":"Schools Week: Louise Haigh, shadow digital minister","url":"https://schoolsweek.co.uk/20899/"}},{"phase":"career","start":"2008","end":"2009","title":"Staff in the office of Graham Allen MP","organisation":"House of Commons","detail":"Worked in the parliamentary office of Graham Allen MP.","source":{"title":"Schools Week: Louise Haigh, sh