idate for Sheffield Heeley","organisation":"Labour Party","detail":"Was selected as the Labour candidate for Sheffield Heeley from an all women shortlist.","source":{"title":"History of Parliament: Louise Haigh","url":"https://membersafter1832.historyofparliamentonline.org/members/9977"}},{"phase":"politics","start":"2015-05","end":"2015-05","title":"Labour candidate, Sheffield Heeley","organisation":"Labour Party","detail":"Won Sheffield Heeley for Labour at the 2015 general election with 20,269 votes.","source":{"title":"Who Can I Vote For: Louise Haigh","url":"https://whocanivotefor.co.uk/person/4421"}}]$bt$::jsonb),
  (4504, 23, $bt$[{"phase":"education","start":null,"end":null,"title":"Westminster City School","organisation":"Westminster City School","detail":"Attended Westminster City School, a state comprehensive school in London.","source":{"title":"politics.co.uk: Wes Streeting","url":"https://www.politics.co.uk/people/wes-streeting/"}},{"phase":"education","start":null,"end":"2004","title":"BA History","organisation":"Selwyn College, Cambridge","detail":"Read history at Selwyn College, Cambridge, where he was president of the Junior Common Room.","source":{"title":"Selwyn College: Streeting visit","url":"https://www.sel.cam.ac.uk/news/streeting-visit"}},{"phase":"politics","start":null,"end":null,"title":"Briefly left the Labour Party","organisation":"Labour Party","detail":"Left the Labour Party for a time as a student in opposition to the Iraq War.","source":{"title":"politics.co.uk: Wes Streeting","url":"https://www.politics.co.uk/people/wes-streeting/"}},{"phase":"career","start":"2004","end":"2005","title":"President, Cambridge University Students' Union","organisation":"Cambridge University Students' Union","detail":"Served as the full time president of Cambridge University Students' Union.","source":{"title":"politics.co.uk: Wes Streeting","url":"https://www.politics.co.uk/people/wes-streeting/"}},{"phase":"career","start":null,"end":null,"title":"Part time staff","organisation":"Progress","detail":"Worked part time for the Progress think tank.","source":{"title":"The Guardian: Wes Streeting: Plenty to shout about","url":"https://www.theguardian.com/education/2008/jun/24/students.highereducationprofile"}},{"phase":"career","start":null,"end":null,"title":"Part time staff","organisation":"Comet","detail":"Worked part time at the retailer Comet.","source":{"title":"The Guardian: Wes Streeting: Plenty to shout about","url":"https://www.theguardian.com/education/2008/jun/24/students.highereducationprofile"}},{"phase":"career","start":null,"end":null,"title":"Part time 