  (4620, 13, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Cator Park Secondary School","detail":"She attended Cator Park Secondary School in Penge after Adamsrill Primary School in Sydenham.","source":{"title":"Ellie Reeves - Politics.co.uk","url":"https://www.politics.co.uk/people/ellie-reeves/"}},{"phase":"education","start":"1999","end":null,"title":"Law degree","organisation":"St Catherine's College, Oxford","detail":"She matriculated at St Catherine's College, Oxford in 1999 to read law.","source":{"title":"The Year 2017, St Catherine's College, Oxford","url":"https://www.stcatz.ox.ac.uk/wp-content/uploads/2018/10/Catz-The-Year-2017.pdf"}},{"phase":"education","start":"2004","end":"2004","title":"Called to the Bar","organisation":null,"detail":"She was called to the Bar in 2004.","source":{"title":"Attorney General swearing in speech: Rt Hon Ellie Reeves KC MP (GOV.UK)","url":"https://www.gov.uk/government/speeches/attorney-general-swearing-in-speech-rt-hon-ellie-reeves-kc-mp"}},{"phase":"career","start":null,"end":null,"title":"Employment rights lawyer","organisation":null,"detail":"She worked as an employment rights lawyer for over 10 years, mainly representing Unite and UCATT trade union members.","source":{"title":"About me - Ellie Reeves","url":"https://elliereeves.com/about/"}},{"phase":"career","start":null,"end":null,"title":"Trade union litigation","organisation":null,"detail":"She represented trade unions in a court case for Gate Gourmet workers and for UCATT on blacklisting.","source":{"title":"Politics is sometimes a long game (Progress)","url":"https://archive.progressivebritain.org/2016/09/20/politics-is-sometimes-a-long-game/"}},{"phase":"career","start":null,"end":null,"title":"Founder, maternity discrimination advice business","organisation":null,"detail":"She set up her own business providing help to working mothers and women facing maternity discrimination.","source":{"title":"About me - Ellie Reeves","url":"https://elliereeves.com/about/"}},{"phase":"politics","start":null,"end":null,"title":"Joined the Labour Party","organisation":"Labour Party","detail":"She joined the Labour Party aged 15.","source":{"title":"About me - Ellie Reeves","url":"https://elliereeves.com/about/"}},{"phase":"politics","start":"2001","end":"2001","title":"Chair, Oxford University Labour Club","organisation":"Oxford University Labour Club","detail":"She chaired the Oxford University Labour Club in 2001.","source":{"title":"Wikipedia: Ellie Reeves","url":"https://en.wikipedia.org/wiki/Ellie_Reeves"}},{"phase":"politics","start":null,"end":null,"title":"National Chair, Labour Students","organisation":"Labour Students","detail":"She served as national chair of Labour Students.","source":{"title":"Politics is sometimes a long game (Progress)","url":"https://archive.progressivebritain.org/2016/09/20/politics-is-sometimes-a-long-game/"}},{"phase":"politics","start":"2006","end":"2016","title":"Member, National Executive Committee","organisation":"Labour Party","detail":"She served on the Labour Party National Executive Committee from 2006 to 2016, first elected at 25 in the constituency section.","source":{"title":"About me - Ellie Reeves","url":"https://elliereeves.com/about/"}},{"phase":"politics","start":"2015","end":"2016","title":"Vice Chair, National Executive Committee","organisation":"Labour Party","detail":"She served as vice chair of the National Executive Committee.","source":{"title":"Wikipedia: Ellie Reeves","url":"https://en.wikipedia.org/wiki/Ellie_Reeves"}},{"phase":"politics","start":null,"end":null,"title":"Vice Chair, London Labour Party","organisation":"London Labour Party","detail":"She was vice chair of the London Labour Party when selected in 2017.","source":{"title":"Former Labour official Ellie Reeves selected for safe seat in London (LabourList)","url":"https://labourlist.org/2017/04/ellie-reeves-selected-to-fight-lewisham-west-penge/"}},{"phase":"politics