  (5039, 14, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Cathays High School","detail":"He spent one year at Cathays High School in Cardiff after moving from India aged 12.","source":{"title":"Rising stars who could play a big part in a Labour government (The Guardian)","url":"https://www.theguardian.com/politics/article/2024/jun/05/rising-stars-who-could-play-a-big-part-in-a-labour-government"}},{"phase":"education","start":null,"end":null,"title":"Secondary education, full scholarship","organisation":"Eton College","detail":"He attended Eton College on a full scholarship after his Welsh teacher at Cathays High School encouraged him to apply.","source":{"title":"The extraordinary story of the talented boy, 12, who used to sleep on a small Cardiff flat floor (WalesOnline)","url":"https://www.walesonline.co.uk/news/wales-news/extraordinary-story-talented-boy-12-29956358"}},{"phase":"education","start":null,"end":null,"title":"BA Philosophy, Politics and Economics","organisation":"Balliol College, Oxford","detail":"He studied philosophy, politics and economics at Balliol College, Oxford.","source":{"title":"Kanishka Narayan - Politics.co.uk","url":"https://www.politics.co.uk/people/kanishka-narayan/"}},{"phase":"education","start":null,"end":null,"title":"MBA","organisation":"Stanford University","detail":"He gained an MBA from Stanford University.","source":{"title":"The extraordinary story of the talented boy, 12, who used to sleep on a small Cardiff flat floor (WalesOnline)","url":"https://www.walesonline.co.uk/news/wales-news/extraordinary-story-talented-boy-12-29956358"}},{"phase":"career","start":"2012","end":"2016","title":"Civil servant, economic adviser to ministers","organisation":"UK Civil Service","detail":"His LinkedIn profile listed him as a civil servant offering economic advice to ministers from 2012 to 2016.","source":{"title":"Newly promoted Welsh MP deletes private sector roles from CV (Nation.Cymr