inkedIn profile listed two years at the London office of Clocktower Ventures, a California investment firm focused on financial technology.","source":{"title":"Newly promoted Welsh MP deletes private sector roles from CV (Nation.Cymru)","url":"https://nation.cymru/news/newly-promoted-welsh-mp-deletes-private-sector-roles-from-cv/"}},{"phase":"career","start":null,"end":null,"title":"Volunteer","organisation":"Citizens Advice; Trussell Trust","detail":"He volunteered for Citizens Advice and the Trussell Trust and mentored young people from South Wales.","source":{"title":"General election 2024: Find out more about the candidates standing in the Vale of Glamorgan (WalesOnline)","url":"https://www.walesonline.co.uk/news/politics/general-election-2024-candidates-standing-28373998"}},{"phase":"politics","start":null,"end":null,"title":"Joined the Labour Party","organisation":"Labour Party","detail":"He joined the Labour Party at 18.","source":{"title":"Labour's Kanishka Narayan ready for General Election fight (Barry and District News)","url":"https://www.barryanddistrictnews.co.uk/news/elections/general_election_2010/vale_of_glamorgan_election_news/24388207.labours-kanishka-narayan-ready-general-election-fight/"}},{"phase":"politics","start":null,"end":null,"title":"Head of tech policy for the shadow digital secretary","organisation":"Labour Party","detail":"He served as head of tech policy for Labour's shadow digital secretary.","source":{"title":"Kanishka Narayan - Politics.co.uk","url":"https://www.politics.co.uk/people/kanishka-narayan/"}},{"phase":"politics","start":"2023","end":"2023","title":"Selected as Labour candidate for Vale of Glamorgan","organisation":"Labour Party","detail":"He was selected as the Labour candidate for the Vale of Glamorgan and moved to Barry a couple of weeks later.","source":{"title":"Wikipedia: Kanishka Narayan","url":"https://en.wikipedia.org/wiki/Kanishka_Narayan"}}]$bt$::jsonb),
  (5148, 14, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Westminster School","detail":"He attended Westminster School.","source":{"title":"Hamish Falconer - Politics.co.uk","url":"https://www.politics.co.uk/people/hamish-falconer/"}},{"phase":"education","start":null,"end":"2008","title":"BA Human, Social and Political Science","organisation":"St John's College, Cambridge","detail":"He studied human, social and political science at St John's College, Cambridge, graduating in 2008.","source":{"title":"Hamish Falconer - Politics.co.uk","url":"https://www.politics.co.uk/people/hamish-falconer/"}},{"phase":"education","start":null,"end":null,"title":"Study at Birkbeck","organisation":"Birkbeck, University of London","detail":"He studied at Birkbeck as well as Cambridge.","source":{"title":"Scholar Spotlight: Hamish Falconer (Yale MacMillan Center)","url":"https://macmillan.yale.edu/stories/scholar-spotlight-hamish-falconer"}},{"phase":"career","start":null,"end":null,"title":"Civil servant, security and transport","organisation":"UK Civil Service","detail":"On graduating he joined the civil service in London working on security and the transport network, then transferred to international work including a short period in Yemen.","source":{"title":"Yale Greenberg World Fellows Interview Series: Hamish Falconer (The Yale Globalist)","url":"https://globalist.yale.edu/onlinecontent/yale-greenberg-world-fellows-interview-series-hamish-falconer"}},{"phase":"career","start":"2009","end":"2013","title":"Department for International Development","organisation":"Department for International Development","detail":"He worked on humanitarian response and state building, including postings in Pakistan and two years in South Sudan.","source":{"title":"Wikipedia: Hamish Falconer","url":"https://en.wikipedia.org/wiki/Hamish_Falconer"}},{"phase":"career","start":null,"end":null,"title":"Human trafficking investigations","organisation":"National Crime Agency","detail":"He worked for the National Crime Agency on investigating human trafficking.","source":{"title":"Former Cabinet Office, Treasury and DWP civil servants among today's election candidates (Civil Service World)","url":"https://www.civilserviceworld.com/professions/article/former-cabinet-office-treasury-and-dwp-civil-servants-among-todays-election-candidates"}},{"phase":"career","start":null,"end":"2022","title":"Diplomat","organisation":"Foreign, Commonwealth and Development Office","detail":"He served in the diplomatic service, leading the Terrorism Response Team and UK efforts to start a peace process in Afghanistan, and left the Foreign Office in 2022.","source":{"title":"Hamish Falconer - Politics.co.uk","url":"https://www.politics.co.uk/people/hamish-falconer/"}},{"phase":"career","start":null,"end":null,"title":"Head, Terrorism Response Team","organisation":"Foreign, Commonwealth and Development Office","detail":"He led the Foreign Office Terrorism Response Team and UK efforts to start a peace process in Afghanistan.","source":{"title":"Former Cabinet Office, Treasury and DWP civil servants among today's election candidates (Civil Service World)","url":"https://www.civilserviceworld.com/professions/article/former-cabinet-office-treasury-and-dwp-civil-servants-among-todays-election-candidates"}},{"phase":"career","start":null,"end":null,"title":"Hostage negotiator","organisation":"Foreign, Commonwealth and Development Office","detail":"He secured the release of Peter Jouvenal, one of five British hostages taken by the Taliban in Afghanistan in 2021.","source":{"title":"Hamish Falconer: We will be forming a government under much harder conditions than 1997 (New Statesman)","url":"https://www.newstatesman.com/the-weekend-interview/2024/06/hamish-falconer-we-will-be-forming-a-government-under-much-harder-conditions-than-1997"}},{"phase":"career","start":"2020","end":"2020","title":"Greenberg World Fellow","organisation":"Yale University","detail":"While on leave from the diplomatic service he was a Fall 2020 World Fellow at Yale.","source":{"title":"Scholar Spotlight: Hamish Falconer (Yale MacMillan Center)","url":"https://macmillan.yale.edu/stories/scholar-spotlight-hamish-falconer"}},{"phase":"career","start":null,"end":"2021-02","title":"European Studies Council Visiting Fellow","organisation":"Yale University","detail":"He remained at Yale through February 2021 as a European Studies Council Visiting Fellow after his World Fellowship.","source":{"title":"Scholar Spotlight: Hamish Falconer (Yale MacMillan Center)","url":"https://macmillan.yale.edu/stories/scholar-spotlight-hamish-falconer"}},{"phase":"career","start":"2022","end":null,"title":"Associate Fellow","organisation":"Institute for Public Policy Research","detail":"After leaving the Foreign Office in 2022 he worked as an associate fellow at IPPR.","source":{"title":"Hamish Falconer - Politics.co.uk","url":"https://www.politics.co.uk/people/hamish-falconer/"}},{"phase":"career","start":null,"end":null,"title":"Policy Fellow","organisation":"Labour Together","detail":"He was a policy fellow at Labour Together while standing as a parliamentary candidate.","source":{"title":"Hamish Falconer - Politics.co.uk","url":"https://www.politics.co.uk/people/hamish-falconer/"}},{"phase":"politics","start":"2022-12","end":"2022-12","title":"Selected as Labour candidate for Lincoln","organisation":"Labour Party","detail":"He was chosen as Labour candidate for Lincoln ahead of councillor Naomi Tweddle.","source":{"title":"Greatest privilege of my life: Lincoln's Labour candidate named (The Lincolnite)","url":"https://thelincolnite.co.uk/2022/12/greatest-privilege-of-my-life-lincolns-labour-candidate-named/"}}]$bt$::jsonb),
  (529, 7, $bt$[{"phase":"education","start":null,"end":null,"title":"Secondary education","organisation":"Blackfyne Grammar School, Consett","detail":"Attended Blackfyne school in Consett, then a grammar school and later Blackfyne Comprehensive School.","source":{"title":"politics.co.uk: Alan Campbell","url":"https://www.politics.co.uk/people/alan-campbell/"}},{"phase":"education","start":null,"end":null,"title":"BA Politics","organisation":"Lancaster University","detail":"Studied politics at Lancaster University.","source":{"title":"politics.co.uk: Alan Campbell","url":"https://www.politics.co.uk/people/alan-campbell/"}},{"phase":"education","start":null,"end":null,"title":"Postgraduate Certificate in Education","organisation":"University of Leeds","detail":"Gained a PGCE at the University of Leeds.","source":{"title":"politics.co.uk: Alan Campbell","url":"https://www.politics.co.uk/people/alan-campbell/"}},{"phase":"education","start":null,"end":null,"title":"MA History","organisation":"Newcastle Polytechnic (now Northumbria University)","detail":"Gained a master's degree in history at Newcastle Polytechnic.","source":{"title":"politics.co.uk: Alan Campbell","url":"https://www.politics.co.uk/people/alan-campbell/"}},{"phase":"career","start":"1981","end":null,"title":"History teacher","organisation":"Whitley Bay High School","detail":"Taught history at Whitley Bay High School for eight years.","source":{"title":"Wikipedia: Alan Campbell (politician)","url":"https://en.wikipedia.org/wiki/Alan_Campbell_(politician)"}},{"phase":"career","start":null,"end":null,"title":"Head of Sixth Form","organisation":"Hirst High School, Ashington","detail":"Moved to Hirst High School in Ashington as head of sixth form.","source":{"title":"politics.co.uk: Alan Campbell","url":"https://www.politics.co.uk/people/alan-campbell/"}},{"phase":"career","start":null,"end":"1997","title":"Head of History","organisation":"Hirst High School, Ashington","detail":"Became head of history at Hirst High School and remained there until his election in 1997.","source":{"title":"Wikipedia: Alan Campbell (politician)","url":"https://en.wikipedia.org/wiki/Alan_Campbell_(politician)"}}]$bt$::jsonb),
  (632, 13, $bt$[{"phase":"education","start":null,"end":null,"title":"Park Mains High School","organisation":"Park Mains High School, Erskine","detail":"Attended Park Mains High School in Erskine.","source":{"title":"politics.co.uk: Douglas Alexander","url":"https://www.politics.co.uk/people/douglas-alexander/"}},{"phase":"education","start":"1984","end":null,"title":"Lester B Pearson United World College of the Pacific","organisation":"Lester B Pearson United World College of the Pacific, Canada","detail":"Won a Scottish scholarship to attend the college near Vancouver.","source":{"title":"politics.co.uk: Douglas Alexander","url":"https://www.politics.co.uk/people/douglas-alexander/"}},{"phase":"education","start":null,"end":"1990","title":"Politics and modern history, first class degree","organisation":"University of Edinburgh","detail":"Studied politics and modern history, graduating with a first class degree in 1990.","source":{"title":"politics.co.uk: Douglas Alexander","url":"https://www.politics.co.uk/people/douglas-alexander/"}},{"phase":"education","start":null,"end":null,"title":"Exchange year","organisation":"University of Pennsylvania","detail":"Won a scholarship to study for a year at the University of Pennsylvania during his Edinburgh degree.","source":{"title":"politics.co.uk: Douglas Alexander","url":"https://www.politics.co.uk/people/douglas-alexander/"}},{"phase":"education","start":null,"end":"1993","title":"LLB","organisation":"University of Edinburgh","detail":"Returned to the University of Edinburgh to study law, graduating with distinction in 1993.","source":{"title":"Wikipedia: Douglas Alexander","url":"https://en.wikipedia.org/wiki/Douglas_Alexander"}},{"phase":"career","start":"1988","end":"1988","title":"Campaign worker","organisation":"Michael Dukakis presidential campaign","detail":"Worked on the Michael Dukakis campaign in the 1988 United States presidential election while studying in the United States.","source":{"title":"Wikipedia: Douglas Alexander","url":"https://en.wikipedia.org/wiki/Douglas_Alexander"}},{"phase":"career","start":null,"end":null,"title":"Parliamentary researcher and speechwriter","organisation":"Office of Gordon Brown MP","detail":"Worked as a parliamentary researcher and speechwriter for Gordon Brown.","source":{"title":"politics.co.uk: Douglas Alexander","url":"https://www.politics.co.uk/people/douglas-alexander/"}},{"phase":"career","start":null,"end":null,"title":"Solicitor","organisation":null,"detail":"Worked for a firm of solicitors that provided legal services to trade union members and specialised in industrial injury cases.","source":{"title":"politics.co.uk: Douglas Alexander","url":"https://www.politics.co.uk/people/douglas-alexander/"}},{"phase":"politics","start":"1982","end":"1982","title":"Joined the Labour Party","organisation":"Labour Party","detail":"Joined the Labour Party as a schoolboy.","source":{"title":"Wikipedia: Douglas Alexander","url":"https://en.wikipedia.org/wiki/Douglas_Alexander"}},{"phase":"politics","start":"1995","end":"1995","title":"Selected as Labour candidate for Perth and Kinross byelection","organisation":"Labour Party","detail":"Selected to stand for Westminster for the first time, in the Perth and Kinross byelection.","source":{"title":"Holyrood: Trading places: back in government, Douglas Alexander is a new man","url":"https://www.holyrood.com/news/view,trading-places-back-in-government-douglas-alexander-is-a-new-man"}},{"phase":"politics","start":"1995-05","end":"1995-05","title":"Labour candidate, Perth and Kinross byelection","organisation":"Labour Party","detail":"Stood for Labour in the Perth and Kinross byelection, which was won by the SNP.","source":{"title":"UK Parliament Members API: Douglas Alexander biography","url":"https://members-api.parliament.uk/api/Members/632/Biography"}},{"phase":"politics","start":"1997-05","end":"1997-05","title":"Labour candidate for Perth","organisation":"Labour Party","detail":"Stood for Labour in Perth at the 1997 general election and came third with 11,036 votes.","source":{"title":"UK Parliament: 1997 General Election, Perth","url":"https://api.parliament.uk/uk-general-elections/elections/23585"}},{"phase":"politics","start":"1997-11","end":"1997-11","title":"Labour candidate, Paisley South","organisation":"Labour Party","detail":"Elected at the Paisley South byelection on 6 November 1997.","source":{"title":"History of Parliament: Douglas Alexander","url":"https://membersafter1832.historyofparliamentonline.org/members/60"}}]$bt$::jsonb);

UPDATE public.mp_biography b SET background_timeline = n.tl, background_last_checked = DATE '2026-10-31'
  FROM bt_new n WHERE b.member_id = n.member_id AND b.background_timeline IS NULL;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  existing_changed integer;
  matching integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (1446, 1510, 3914, 4038, 4046, 4077, 4082, 4119, 4263, 4359, 4473, 4504, 4620, 4641, 491, 5038, 5039, 5148, 529, 632) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO existing_changed FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE o.had AND md5(coalesce(b.background_timeline::text, '')) IS DISTINCT FROM o.th;
  SELECT count(*) INTO matching FROM public.mp_biography b JOIN bt_new n USING (member_id)
   WHERE b.background_timeline = n.tl AND jsonb_array_length(b.background_timeline) = n.n AND b.background_last_checked = DATE '2026-10-31';
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT sum(jsonb_array_length(background_timeline)) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'rows changed %, outside the 20 %, existing timelines changed %, rows matching the file %, MPs with a timeline %, entries %',
    changed, changed_outside, existing_changed, matching, with_timeline, entry_total;
  IF changed <> 20 THEN RAISE EXCEPTION 'expected exactly 20 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 20 changed', changed_outside; END IF;
  IF existing_changed <> 0 THEN RAISE EXCEPTION '% of the 29 existing timelines changed', existing_changed; END IF;
  IF matching <> 20 THEN RAISE EXCEPTION 'expected 20 rows matching the file, got %', matching; END IF;
  IF with_timeline <> 49 THEN RAISE EXCEPTION 'expected 49 MPs with a timeline after, got %', with_timeline; END IF;
  IF entry_total <> 639 THEN RAISE EXCEPTION 'expected 639 entries, got %', entry_total; END IF;
END $$;

COMMIT;
